import json
from hypothesis import strategies as st

@st.composite
def gen(draw):
    half = draw(st.integers(1, 6))
    n = 2 * half
    mode = draw(st.sampled_from(["random", "allzero", "allone", "sorted", "alt"]))
    if mode == "random":
        s = draw(st.text(alphabet="01", min_size=n, max_size=n))
    elif mode == "allzero":
        s = "0" * n
    elif mode == "allone":
        s = "1" * n
    elif mode == "sorted":
        k = draw(st.integers(0, n))
        s = "0" * k + "1" * (n - k)
    else:
        s = "".join("01"[i % 2] for i in range(n))
    return json.dumps(s)

def validate(inp):
    try:
        s = json.loads(inp.strip())
    except Exception:
        return False
    if not isinstance(s, str):
        return False
    n = len(s)
    if n < 2 or n > 10**5 or n % 2 != 0:
        return False
    return all(c in "01" for c in s)

def ref(inp):
    s = json.loads(inp.strip())
    n = len(s)
    INF = float("inf")
    dp = [INF] * (n + 1)
    dp[0] = 0
    for j in range(1, n + 1):
        for i in range(0, j):
            if (j - i) % 2 != 0:
                continue
            seg = s[i:j]
            for c in "01":
                cost = sum(1 for ch in seg if ch != c)
                if dp[i] + cost < dp[j]:
                    dp[j] = dp[i] + cost
    return json.dumps(dp[n])
