import json
from hypothesis import strategies as st

@st.composite
def gen(draw):
    n = draw(st.sampled_from([2, 4, 6, 8, 10]))
    kind = draw(st.integers(0, 4))
    if kind == 0:
        s = draw(st.text(alphabet="01", min_size=n, max_size=n))
    elif kind == 1:
        s = "0" * n
    elif kind == 2:
        s = "1" * n
    elif kind == 3:
        half = n // 2
        s = "0" * half + "1" * half
    else:
        s = "".join(draw(st.sampled_from(["0", "1"])) for _ in range(n))
    return json.dumps(s)

def validate(inp):
    try:
        s = json.loads(inp)
    except Exception:
        return False
    if not isinstance(s, str):
        return False
    n = len(s)
    return 2 <= n <= 10**5 and n % 2 == 0 and all(c in "01" for c in s)

def _beautiful(t):
    # Literal definition: can t be partitioned into >=1 substrings,
    # each of even length and uniform in character.
    n = len(t)
    dp = [False] * (n + 1)
    dp[0] = True
    for j in range(1, n + 1):
        for i in range(j):
            if dp[i] and (j - i) % 2 == 0 and len(set(t[i:j])) == 1:
                dp[j] = True
                break
    return dp[n]

def ref(inp):
    s = json.loads(inp)
    n = len(s)
    best = None
    for mask in range(1 << n):
        t = "".join("1" if (mask >> k) & 1 else "0" for k in range(n))
        if not _beautiful(t):
            continue
        cost = sum(1 for a, b in zip(s, t) if a != b)
        if best is None or cost < best:
            best = cost
    return json.dumps(best)
